// 仅提供有界命令意图；按下按钮仍走正式preview/commit，不把此页当成资源授权证明。
#include "naval_repair_views.hpp"
#include "naval_repair_charges_codec.hpp"
#include "resident/storage/common_codec.hpp"
#include <algorithm>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;using A=V::Array;
template<class T>const T* find(const std::vector<T>& rows,const StableId& id){for(const auto& row:rows)if(row.id==id)return &row;return nullptr;}
const NavalRepairChargeFact* charge_for(const NavalState& n,const StableId& id){for(const auto& r:n.repair_charges.charges)if(r.action_id==id)return &r;return nullptr;}
const NavalRepairResult* result_for(const NavalState& n,const StableId& id){for(const auto& r:n.repairs.results)if(r.action_id==id)return &r;return nullptr;}
}
// 未启用不返回半功能页；无实际指挥者只得空选项而不取得他人舰队资料。
Outcome<V> naval_repair_page(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& access,const NavalState& n,const NavalCatalog& catalog,const StableId& actor){if(!catalog.repair_policy)return {false,{},common_failure("NavalRepairProfileRequired").error};if(!c.actor(actor))return {false,{},common_failure("UnknownActor",actor).error};A options,history;V active;bool limited=false;const NavalFleetRecord* fleet=nullptr;for(const auto& f:n.fleets)if(f.status=="active"&&f.commander_actor_id==actor){if(fleet)return {false,{},common_failure("NavalCommanderAssignedTwice",actor).error};fleet=&f;}
 for(auto i=n.repairs.starts.rbegin();i!=n.repairs.starts.rend();++i)if(i->terms.actor_id==actor){const auto* result=result_for(n,i->id);const auto* charge=charge_for(n,i->id);if(!result){const auto* action=c.action(i->id);active=boundary::obj({{"action_id",V{i->id}},{"vessel_id",V{i->terms.vessel_id}},{"remaining_ticks",V{action?action->remaining_ticks:Integer{0}}},{"duration",V{i->terms.duration}},{"integrity_after",V{i->terms.integrity_after}}});if(charge)active.as<V::Dict>()->emplace_back("charge",naval_repair_charges_codec::encode_terms(charge->terms));}else if(history.size()<16){auto row=boundary::obj({{"source_id",V{result->id}},{"vessel_id",V{i->terms.vessel_id}},{"tick",V{result->tick}},{"success",V{result->success}},{"reason",V{result->reason}}});if(charge){row.as<V::Dict>()->emplace_back("paid",V{result->success?charge->terms.amount:Integer{0}});row.as<V::Dict>()->emplace_back("released",V{result->success?Integer{0}:charge->terms.amount});}history.push_back(std::move(row));}}

 if(fleet&&!active.as<V::Dict>()){
  std::vector<StableId> inventories;for(const auto& b:fleet->assignments){const auto* vessel=find(n.vessels,b.vessel_id);if(vessel)inventories.push_back(vessel->cargo_inventory_id);for(const auto& id:b.extra_inventory_ids)inventories.push_back(id);}std::sort(inventories.begin(),inventories.end());inventories.erase(std::unique(inventories.begin(),inventories.end()),inventories.end());if(inventories.size()>128){inventories.resize(128);limited=true;}
  for(const auto& b:fleet->assignments){const auto* vessel=find(n.vessels,b.vessel_id);if(!vessel)continue;for(const auto& rule:catalog.repair_policy->rules){if(rule.hull_id!=vessel->hull_id)continue;if(options.size()>=64){limited=true;break;}NavalRepairStart chosen;Outcome<NavalRepairQuote> quote;bool observed=false;for(const auto& inventory:inventories){NavalRepairStart request{"repair-view:"+std::to_string(c.revision())+":"+std::to_string(options.size()),fleet->id,vessel->id,rule.id,inventory};auto trial=preview_naval_repair(c,m,mc,access,n,catalog,actor,request);if(!observed||trial.ok){chosen=request;quote=std::move(trial);observed=true;}if(quote.ok)break;}if(!observed)continue;A materials;for(const auto& item:rule.materials)materials.push_back(boundary::obj({{"item_id",V{item.first}},{"quantity",V{item.second}}}));options.push_back(boundary::obj({{"vessel_id",V{vessel->id}},{"rule_id",V{rule.id}},{"duration",V{rule.duration}},{"minimum_crew",V{rule.minimum_crew}},{"materials",V{std::move(materials)}},{"integrity_before",V{vessel->integrity}},{"integrity_after",V{quote.ok?quote.value.terms.integrity_after:vessel->integrity}},{"ok",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}},{"params",boundary::obj({{"request_key",V{chosen.request_key}},{"fleet_id",V{chosen.fleet_id}},{"vessel_id",V{chosen.vessel_id}},{"rule_id",V{chosen.rule_id}},{"inventory_id",V{chosen.inventory_id}}})}}));if(catalog.repair_charge_policy){Integer fee=0;StableId service_id;const auto* here=std::get_if<SettlementLocation>(&c.actor(actor)->location);if(here)for(const auto& service:catalog.repair_charge_policy->services)if(service.rule_id==rule.id&&service.berth_place_id==here->place_id){fee=service.fee;service_id=service.id;}options.back().as<V::Dict>()->emplace_back("fee",V{fee});options.back().as<V::Dict>()->emplace_back("service_id",V{service_id});}}if(options.size()>=64)break;}
 }
 auto out=boundary::obj({{"active",std::move(active)},{"options",V{std::move(options)}},{"history",V{std::move(history)}},{"limited",V{limited}}});if(catalog.repair_charge_policy)out.as<V::Dict>()->emplace_back("charges_enabled",V{true});return {true,std::move(out),{}};
}
}
